script:
async () => {
  // Mac M2 session, M12 fix round, measurement A: M1's extension (wgsl-compile-all.json,
  // Chrome 154) run in Safari 27.0.1 on ?mode=B. Same method as M1: every other WGSL module
  // of the app compiled on a fresh device, getCompilationInfo plus a validation and an
  // internal error scope around createShaderModule; the live renderer's device is left alone.
  // Changes forced by Safari, which has no 'subgroups' feature: the device is requested
  // without features, and cull is counted as the engine builds it here,
  // prepareShaderSource(cull, false) (the BEGIN/END-SUBGROUPS-ONLY region stripped). The two
  // subgroup variants of M1 go to `extra`, next to the modules nothing imports: the engine
  // never builds them in Safari, and they are expected to fail.
  // As in M1, `results` builds no pipeline (M1: "Pipelines are exercised by the harness
  // tabs (M2)"). The primitive and sort pipelines are in wgsl-validation-safari.json.
  // Added beyond M1, `pipelines`: the pipelines of the three modules whose harness checks
  // read no pixel, built by the engine's own code inside the same two error scopes:
  // ParticleSystem.buildSimulate / buildRender (the calls of the renderer and of the
  // particle hot-reload, with the canvas format) and DebugLinePass.setup (LineBatchPass,
  // debug-line.wgsl). Nothing is drawn.
  const { prepareShaderSource } = await import('/src/render/passes/cull-pass.ts');
  const { ParticleSystem } = await import('/src/particle-system.ts');
  const { DebugLinePass, LineBatchPass } = await import('/src/render/passes/debug-line-pass.ts');
  const adapter = await navigator.gpu.requestAdapter();
  const device = await adapter.requestDevice();
  const deviceFeatures = [...device.features].sort();
  const src = async (name, imported) => imported
    ? (await import(`/src/shaders/${name}.wgsl?raw`)).default
    : await (await fetch(`/src/shaders/${name}.wgsl`)).text();
  const compile = async (label, code) => {
    device.pushErrorScope('internal');
    device.pushErrorScope('validation');
    let module = null, thrown = null;
    try { module = device.createShaderModule({ code, label }); } catch (e) { thrown = String(e); }
    const validation = await device.popErrorScope();
    const internal = await device.popErrorScope();
    const info = module ? await module.getCompilationInfo() : { messages: [] };
    return {
      label, bytes: code.length,
      errors: info.messages.filter((m) => m.type === 'error').length,
      messages: info.messages.map((m) => `${m.type} ${m.lineNum}:${m.linePos} ${m.message}`),
      scope: [thrown, validation?.message, internal?.message].filter(Boolean),
    };
  };
  const scoped = async (label, build) => {
    device.pushErrorScope('internal');
    device.pushErrorScope('validation');
    let built = null, thrown = null;
    try { built = build(); } catch (e) { thrown = String(e); }
    const validation = await device.popErrorScope();
    const internal = await device.popErrorScope();
    return { label, built, scope: [thrown, validation?.message, internal?.message].filter(Boolean) };
  };

  const cull = await src('cull', true);
  const results = [
    await compile('cull (atomic: region stripped, as the engine builds it without subgroups)', prepareShaderSource(cull, false)),
  ];
  const sources = {};
  for (const name of ['scatter', 'fxaa-tonemap', 'selection-seed', 'jfa', 'outline-composite', 'bloom',
    'particle-simulate', 'particle-render', 'debug-line', 'sdf-jfa', 'light-accum', 'pixel-probe',
    'transparent-gather', 'transparent-sort']) {
    sources[name] = await src(name, true);
    results.push(await compile(name, sources[name]));
  }
  // Not built by the engine in Safari (no 'subgroups'), or not imported anywhere live: reported, not counted.
  const extra = [
    await compile("cull (subgroups: not built in Safari, no 'subgroups' feature)", prepareShaderSource(cull, true)),
    await compile("cull (subgroups + subgroup_id: not built in Safari, no 'subgroups' feature)", prepareShaderSource(cull, true, true)),
    await compile('prefix-sum (+ enable subgroups; not imported)', 'enable subgroups;\n' + await src('prefix-sum', false)),
    await compile('basic-binding-array (design artifact, not imported)', await src('basic-binding-array', false)),
  ];

  const format = navigator.gpu.getPreferredCanvasFormat();
  const particles = new ParticleSystem(device);
  const line = new DebugLinePass(1);
  const pipelines = [
    await scoped('particle-simulate: simulate + spawn (ParticleSystem.buildSimulate, layout auto)',
      () => Object.keys(particles.buildSimulate(sources['particle-simulate']))),
    await scoped(`particle-render: render (ParticleSystem.buildRender, layout auto, ${format})`,
      () => Object.keys(particles.buildRender(sources['particle-render'], format))),
    await scoped(`debug-line: LineBatchPass.setup (explicit layout, line-list, ${format})`,
      () => { line.setup(device, null); return ['pipeline']; }),
  ];
  particles.destroy();
  line.destroy();
  device.destroy();
  return {
    ok: results.every((r) => r.errors === 0 && r.scope.length === 0),
    pipelinesOk: pipelines.every((p) => p.scope.length === 0),
    adapter: adapter.info.description,
    deviceFeatures,
    canvasFormat: format,
    debugLineSourceIsTheLiveOne: LineBatchPass.SHADER_SOURCE === sources['debug-line'],
    crossOriginIsolated: window.crossOriginIsolated === true,
    navigatorGpu: !!navigator.gpu,
    visibility: document.visibilityState,
    results, extra, pipelines,
  };
}
